// Set / change the working directory for ONE chat tab. Each tab's agent runs in its
// own folder, so you can point different tabs at different projects. Picks a folder,
// registers it with the backend sandbox (so reads/writes are allowed), and — if it's
// the active tab — switches the file explorer to match.
async function _setChatTabFolder(idx) {
  const s = _chatSessions[idx];
  if (!s) return;
  let picked;
  try { picked = await backend.pickFolder(); } catch { picked = null; }
  if (!picked) return;
  s.project = picked;
  if (inTauri && !workspaceRoots.includes(picked)) {
    try { await backend.registerWorkspaceRoot(picked); }
    catch (e) { if (inTauri) showToast(`⚠️ 设置「${basename(picked)}」失败：${String(e?.message || e).slice(0, 80)}`); }
  }
  _renderChatTabs();
  saveChatHistory();
  // If this is the tab you're looking at, point the explorer + active root at it too.
  if (idx === _activeChatIdx) { try { await openFolder(picked); } catch {} }
  showToast(`本标签页工作目录 → ${basename(picked)}`);
}

// Open a SECOND editor window (independent — open another project side-by-side). The
// ?w=sub flag makes it skip restoring/overwriting the main window's session. Tauri only;
// capabilities/default.json must include "win-*" in `windows` for it to use the backend.
async function _openNewWindow() {
  if (!inTauri) { showToast("多窗口仅桌面版可用"); return; }
  try {
    const { WebviewWindow } = await import("@tauri-apps/api/webviewWindow");
    const label = "win-" + Date.now().toString(36);
    const w = new WebviewWindow(label, {
      url: "index.html?w=sub",
      title: "Michael IDE",
      width: 1180, height: 760, minWidth: 880, minHeight: 560,
      resizable: true, titleBarStyle: "Overlay", hiddenTitle: true,
    });
    w.once("tauri://error", (e) => showToast("新窗口打开失败：" + String(e?.payload || "").slice(0, 80)));
  } catch (e) {
    showToast("新窗口打开失败：" + String(e?.message || e).slice(0, 80));
  }
}

async function _switchChatSession(idx) {
  try { _perfPhase("_switchChatSession"); } catch {}
  if (idx === _activeChatIdx || idx < 0 || idx >= _chatSessions.length) return;
  if (_activeChatIdx >= 0 && _chatSessions[_activeChatIdx]) {
    _chatSessions[_activeChatIdx].container.hidden = true;
    _chatSessions[_activeChatIdx].scrollPos = chatEl?.scrollTop || 0;
    _chatSessions[_activeChatIdx].model = loadConfig().model;
  }
  _activeChatIdx = idx;
  const session = _chatSessions[idx];
  // Do not deserialize every archived chat at startup. The selected tab gets its
  // exact event stream before it renders or can form a model request.
  await _ensureSessionTranscript(session);
  if (idx !== _activeChatIdx || session !== _chatSessions[idx]) return;
  await _renderSessionHistory(session); // restored tabs render here, on first view
  session.container.hidden = false;
  _currentAiMode = _normalizeAiMode(session.mode);
  session.mode = _currentAiMode;
  _updateModeUI();
  _agentContextCache = { root: null, ts: 0, data: "" };
  if (session.model) {
    const c = loadConfig();
    if (c.model !== session.model) {
      saveConfig({ ...c, model: session.model });
      refreshModelBadge();
    }
  }
  _renderChatTabs();
  if (chatEl) {
    while (chatEl.firstChild) chatEl.removeChild(chatEl.firstChild);
    chatEl.appendChild(session.container);
    // A freshly-restored tab (IDE just opened, or first time this restored tab is shown) jumps to the
    // NEWEST message instead of a stale saved scroll position — no manual scrolling to catch up.
    if (session._restored) { session._restored = false; _scrollChatBottom(); }
    else chatEl.scrollTop = session.scrollPos || 0;
  }
  _ensureSessionHint(session); // empty tab → show the starter hint inside its container
  _renderQueueBar(session); // 切回标签时同步排队小卡片
  _drainFollowups(session); // returning to a tab whose run finished while away → send its queued follow-up
  // Switch file explorer to this tab's working directory if it resolves to a
  // real folder. Never pass a tab label like "Mrday.one" to openFolder() as if
  // it were an absolute path; that is what made the explorer say "未打开文件夹"
  // while the agent attempted writes in a bogus empty/rootless workspace.
  try { _ensureSessionWorkspaceRoot(session, { open: true }).catch(() => {}); } catch {}
  // The send/stop button reflects whether THIS tab is currently running — each
  // tab has its own agent loop, so switching tabs shows the right button.
  _setSendBtnStop(!!session.streaming);
  // Restore or clear the plan chip for THIS tab's session.
  _clearPlanChip();
  if (session._planActive && session._planSteps && session._planSteps.some((s) => s.status !== "completed" && s.status !== "cancelled")) {
    _syncPlanChip({ session, _planSteps: session._planSteps }, session._planSteps);
  }
  _refreshContextMeterFromDraft({ force: true });
}

function _newChatSession(name, mode) {
  const session = _createChatSession(name, mode);
  _chatSessions.push(session);
  void _switchChatSession(_chatSessions.length - 1);
  saveChatHistory();
  return session;
}

function _disposeChatSession(session) {
  if (!session || session._disposed) return;
  session._disposed = true;
  try { _setStreaming(session, false); } catch {}
  try {
    _releaseMessagesAttachmentUrls(session?.memory?.assemble?.() || session?.memory?.recent || [], session?.container, false);
    _releaseMessagesAttachmentUrls(session?._pendingSends || [], session?.container, false);
    _releaseBlobMediaInNode(session?.container);
  } catch {}
  try { session?.memory?.setRemovalHandler?.(null); } catch {}
  try {
    if (session._cancelIds && session._cancelIds.clear) session._cancelIds.clear();
    session._reqId = "";
    session._pendingSends = [];
    session._steerQueue = null;
    session._runIsLoop = null;
    session._followupDraining = false;
    session._planActive = false;
    session._planSteps = [];
    session._htmlSnapshot = "";
  } catch {}
  try {
    if (session.container) {
      session.container.querySelectorAll?.("video,audio").forEach((media) => { try { media.pause(); media.removeAttribute("src"); media.load?.(); } catch {} });
      session.container.innerHTML = "";
      session.container.remove();
    }
  } catch {}
  session.container = null;
  session.memory = null;
}

function _archiveChatSession(session) {
  if (!session || !_sessionHasRecoverableMemory(session)) return null;
  // The only call site that passes includeHtml=true, and it passed no options — so a closed tab
  // kept a full, TEXT-UNBUDGETED copy of memory.recent + memory.transcript in memory for the
  // process lifetime, x80 tabs. Media (1.5MB) and HTML (360k) were already bounded; text was
  // the one unbounded dimension. Use the same budget shape the on-disk mirror already uses.
  // Deliberately NOT setting recentLimit/transcriptLimit: those desynchronize transcriptOffset
  // from _transcriptLoaded on restore.
  const archived = _chatSessionDataForStorage(session, undefined, true, {
    textBudget: { remaining: CHAT_LOCAL_TEXT_BUDGET, perValue: CHAT_LOCAL_TEXT_PER_VALUE },
  });
  archived.closedAt = Date.now();
  if (!_sessionHasRecoverableMemory(archived)) return null;
  _closedChatSessions = (Array.isArray(_closedChatSessions) ? _closedChatSessions : [])
    .filter((item) => item && item.id !== archived.id);
  _closedChatSessions.unshift(archived);
  if (_closedChatSessions.length > 80) _closedChatSessions.length = 80;
  return archived;
}

function _restoreClosedChatSession(closedIndex) {
  if (closedIndex < 0 || closedIndex >= _closedChatSessions.length) return null;
  const sData = _closedChatSessions[closedIndex];
  const session = _createChatSession(sData.name, sData.mode, sData.model, sData.project ?? "");
  session.id = sData.id || session.id;
  session.created = sData.created || Date.now();
  if (sData.intentState && typeof sData.intentState === "object") session._intentState = sData.intentState;
  if (sData.lastRun && typeof sData.lastRun === "object") session._lastRunState = sData.lastRun;
  if (typeof sData.html === "string" && sData.html) session._htmlSnapshot = sData.html;
  if (sData.memory) {
    session.memory = ConversationMemory.fromJSON(sData.memory);
    session._transcriptLoaded = !(Number.isFinite(sData.memory.transcriptCheckpoint)
      && !(Array.isArray(sData.memory.transcript) && sData.memory.transcript.length));
  }
  else if (Array.isArray(sData.history)) for (const m of sData.history) session.memory.push(m);
  _bindSessionMemoryCleanup(session);
  session._pendingSends = _pendingSendsForStorage(sData.pendingSends);
  session._restored = true;
  _closedChatSessions.splice(closedIndex, 1);
  _chatSessions.push(session);
  void _switchChatSession(_chatSessions.length - 1);
  saveChatHistory();
  return session;
}

function _closeChatSession(idx) {
  if (idx < 0 || idx >= _chatSessions.length) return;
  const closing = _chatSessions[idx];
  _archiveChatSession(closing);
  _disposeChatSession(closing);
  _chatSessions.splice(idx, 1);
  if (_chatSessions.length === 0) {
    // Truly close the last tab — go to an empty state instead of spawning a
    // fresh "Chat N" (which made the tab feel impossible to close and kept
    // bumping the counter). Numbering restarts at 1 next time.
    _activeChatIdx = -1;
    _chatSeq = 0;
    _renderChatTabs();
    if (chatEl) { while (chatEl.firstChild) chatEl.removeChild(chatEl.firstChild); }
    _setSendBtnStop(false);
    _clearPlanChip();
    _setContextMeter({ promptTokens: 0, completionTokens: 0, cachedTokens: null, estimated: true, source: "idle" });
    showChatHint?.();
    saveChatHistory();
    return;
  }
  // Recompute which session stays active after the removal.
  let target = _activeChatIdx;
  if (target > idx) target--;                 // sessions after idx shifted left by one
  else if (target === idx) target = Math.min(idx, _chatSessions.length - 1);
  // target < idx → unchanged
  // Force a full refresh even when target equals the current active index
  // (closing a non-active tab): otherwise _switchChatSession's same-index
  // early-return leaves the just-closed tab still rendered.
  _activeChatIdx = -1;
  void _switchChatSession(target);
  saveChatHistory();
}

// Capture a session's rendered transcript as sanitized HTML, so a restart can
// restore the FULL visual (tool cards, diffs, inline screenshots) — not just the
// text. Transient/interactive bits (spinners, dead buttons) are stripped, and an
// over-large snapshot is skipped so a screenshot-heavy thread can't bloat the
// store (restore then falls back to re-rendering from the text history).
// Remove streaming/ellipsis residue from a transcript root (live container OR a detached
// snapshot clone): dead blinking carets, the "..."/"…" filler paragraphs the weak Claude
// provider streams (they sit as a leading <p>...</p> inside a settled .agent-seg, NOT only
// in .agent-seg--stream), and any .agent-seg left empty after stripping them.
function _scrubResidue(root) {
  if (!root || !root.querySelectorAll) return;
  try {
    // .next-steps = 临时建议 chips（上手引导 / 接下来建议），纯瞬时 UI，绝不该进快照——
    // 否则每次重启被快照保存+恢复、再叠加新的一组 → "重启一直刷上手引导"那个累积 bug。
    // 在 _scrubResidue 里清（保存克隆 6336 + 恢复 6150 都会跑）→ 清掉已累积的 + 防未来再存。
    // .run-revert-btn = 已移除的「撤销本轮全部改动」按钮；.agent-files-bar/.agent-files-list =
    // 已移除的「N Files」汇总条：旧会话快照里已经序列化了它们，
    // 恢复后是没有监听器的死 UI，这里一并清掉（保存+恢复两路都走）。
    root.querySelectorAll(".md-caret, .md-stream-tail, .next-steps, .run-revert-btn, .agent-files-bar, .agent-files-list").forEach((e) => e.remove());
    root.querySelectorAll(".agent-seg p, .msg__body > p").forEach((p) => {
      if (/^[.\s…。·]+$/.test(p.textContent || "")) p.remove();
    });
    root.querySelectorAll(".agent-seg--stream, .agent-seg").forEach((seg) => {
      if (!(seg.textContent || "").trim() && !seg.querySelector("img,video,audio,pre,svg,canvas,button,.agent-tool-step,.atc-viewport"))
        seg.remove();
      else seg.classList.remove("agent-seg--stream");
    });
  } catch {}
}

function _snapshotTranscript(session) {
  try {
    const c = session && session.container;
    // Only snapshot what's actually been rendered; an un-viewed restored tab keeps
    // whatever snapshot it was loaded with (see restoreChatHistory).
    if (!c || !session._rendered) return session?._htmlSnapshot || "";
    // 体积预检：超限的快照最后一定被 _snapshotIsSafeToRestore 丢弃，先花几百毫秒
    // 克隆节点 + 序列化几 MB 再丢是纯浪费。textContent 长度是 innerHTML 的下界，
    // 超限直接截断不存——恢复路径对无快照会话走持久历史重建（_renderSessionHistory）。
    if (c.querySelectorAll(":scope > .msg").length > _SNAPSHOT_MAX_MESSAGES) return "";
    if ((c.textContent || "").length > _SNAPSHOT_MAX_CHARS) return "";
    const clone = c.cloneNode(true);
    // Never persist process-local object URLs, but keep every other rich card.
    // The cloned/live video lists have the same DOM order, so the live node can
    // supply its durable key frame even though cloneNode omits JS properties.
    const liveVideos = Array.from(c.querySelectorAll("video"));
    const clonedVideos = Array.from(clone.querySelectorAll("video"));
    for (let index = 0; index < clonedVideos.length; index++) {
      const clonedVideo = clonedVideos[index];
      const attachment = liveVideos[index]?._mediaAttachment;
      const attachmentId = _ensureAttachmentId(attachment);
      if (attachmentId) clonedVideo.dataset.mediaAttachmentId = attachmentId;
      const src = clonedVideo.getAttribute("src") || clonedVideo.getAttribute("poster") || "";
      if (!src.startsWith("blob:")) continue;
      const frame = Array.isArray(attachment?.frames)
        ? attachment.frames.find((value) => typeof value === "string" && value.startsWith("data:image/"))
        : "";
      if (frame) {
        const image = document.createElement("img");
        image.src = frame;
        image.className = clonedVideo.classList.contains("msg__attached-video") ? "msg__attached-image" : (clonedVideo.className || "");
        image.alt = attachment?.name || "Video key frame";
        image.title = "视频关键帧";
        clonedVideo.replaceWith(image);
      } else {
        clonedVideo.remove();
      }
    }
    // 思考中途被保存：快照里的流式思考卡按「已收起」落盘（补标题/时长/折叠态），
    // 否则恢复后这张卡永远卡在"思考中…"转圈。时长取活卡的 JS 属性（clone 不带）。
    const liveThinks = Array.from(c.querySelectorAll(".think-card"));
    const clonedThinks = Array.from(clone.querySelectorAll(".think-card"));
    for (let index = 0; index < clonedThinks.length; index++) {
      const card = clonedThinks[index];
      if (!card.classList.contains("streaming")) continue;
      card.classList.remove("streaming");
      card.dataset.open = "0";
      const tt = card.querySelector(".think-title");
      if (tt) tt.textContent = "已思考";
      const live = liveThinks[index];
      const ms = live ? (Number.isFinite(live._durMs) ? live._durMs : (live._t0 ? Date.now() - live._t0 : 0)) : 0;
      const d = card.querySelector(".tk-dur");
      if (d && !d.textContent && ms > 0) d.textContent = _fmtThinkDur(ms);
    }
    clone.querySelectorAll(
      ".thinking, .stream-cursor, .plan-exec-btn, .chat-history-page, .chat-earlier-note, [data-transient]"
    ).forEach(e => e.remove());
    _scrubResidue(clone); // never freeze "..." filler / live carets into the snapshot
    const html = clone.innerHTML || "";
    if (!_snapshotIsSafeToRestore(html)) return ""; // restore only a bounded, responsive transcript
    return html;
  } catch { return ""; }
}

let _chatSavePending = false;
