    browserProps.append = { type: "boolean", description: "type/fill 用：追加到现有值；action=append 会强制追加" };
    browserProps.absent = { type: "boolean", description: "wait 用：true 表示等待目标消失/不存在" };
    browserProps.expect = { type: "string", description: "动作后验收：等价于 expectText 的简写；没看到该文本则动作失败并返回原因" };
    browserProps.expectText = { type: "string", description: "动作后验收：必须出现的页面文字/toast/状态文案" };
    browserProps.expectSelector = { type: "string", description: "动作后验收：必须存在的 CSS selector；配合 expectAbsent=true 可验证消失" };
    browserProps.expectUrl = { type: "string", description: "动作后验收：当前 URL 必须包含该片段" };
    browserProps.expectValue = { type: "string", description: "动作后验收：目标输入框/当前焦点值必须包含该值" };
    browserProps.expectAbsent = { type: "boolean", description: "动作后验收：true 表示 expectSelector 指向的元素必须不存在/已消失" };
