    t = t.replace(/\b((?:sk|rk)_live_[A-Za-z0-9]{10,}|SG\.[A-Za-z0-9_-]{16,}|AC[0-9a-f]{30,}|npm_[A-Za-z0-9]{30,}|dop_v1_[a-f0-9]{32,}|shpat_[a-f0-9]{20,})\b/g, (m) => _mk(m, (n) => m.slice(0, 6) + `…[REDACTED${n}]`));
