    t = t.replace(/\b([a-z][a-z0-9+.-]*:\/\/[^\s:@/]+):([^\s:@/]{3,})@/gi, (m, head, pw) => `${head}:${_mk(pw, (n) => `…[REDACTED${n}]`)}@`);
