  const SOURCE_EXT = new Set(["ts", "tsx", "js", "jsx", "mjs", "cjs", "py", "rs", "go", "java", "kt", "kts", "rb", "php", "c", "cc", "cpp", "h", "hpp", "cs", "swift", "scala", "m", "mm", "vue", "svelte", "sh", "bash", "zsh", "sql"]);
