    if (DOC_EXT.has(ext) || base === "readme" || base === "license" || base === "changelog" || base === "authors") { sawDoc = true; continue; }
    // 未知/无后缀（脚本、二进制等）保守当作可能是源码 → 不触发，宁可漏放不误伤纯代码任务。
