const ADAPTIVE_PROFILE_KEY = "michael-ide.adaptive-profile";
const DEFAULT_ADAPTIVE_PROFILE = {
  enabled: true,
  tone: "direct",
  detail: "balanced",
  autonomy: "proactive",
  skill: "auto",
  intentMode: "infer",
};
const ADAPTIVE_PROFILE_OPTIONS = {
  tone: [
    ["direct", "直接真实"],
    ["warm", "温和解释"],
    ["strict", "老手审查"],
  ],
  detail: [
    ["brief", "精简"],
    ["balanced", "平衡"],
    ["deep", "深入"],
  ],
  autonomy: [
    ["proactive", "自动推进"],
    ["confirm", "关键处确认"],
    ["safe", "稳一点"],
  ],
  skill: [
    ["auto", "自动判断"],
    ["novice", "新手友好"],
    ["expert", "老手模式"],
  ],
  intentMode: [
    ["infer", "上下文推断"],
    ["confirm", "不确定才确认"],
    ["ask", "先问清楚"],
  ],
};

function _adaptiveOptionLabel(group, value) {
  return (ADAPTIVE_PROFILE_OPTIONS[group] || []).find(([v]) => v === value)?.[1] || String(value || "");
}

function _normalizeAdaptiveProfile(raw) {
  const next = { ...DEFAULT_ADAPTIVE_PROFILE, ...(raw && typeof raw === "object" ? raw : {}) };
  next.enabled = next.enabled !== false;
  for (const key of ["tone", "detail", "autonomy", "skill", "intentMode"]) {
    const allowed = new Set((ADAPTIVE_PROFILE_OPTIONS[key] || []).map(([v]) => v));
    if (!allowed.has(next[key])) next[key] = DEFAULT_ADAPTIVE_PROFILE[key];
  }
  return next;
}

function _loadAdaptiveProfile() {
  try {
    if (typeof localStorage === "undefined") return { ...DEFAULT_ADAPTIVE_PROFILE };
    const raw = localStorage.getItem(ADAPTIVE_PROFILE_KEY);
    return _normalizeAdaptiveProfile(raw ? JSON.parse(raw) : null);
  } catch {
    return { ...DEFAULT_ADAPTIVE_PROFILE };
  }
}

function _saveAdaptiveProfile(profile) {
  const next = _normalizeAdaptiveProfile(profile);
  try {
    if (typeof localStorage !== "undefined") localStorage.setItem(ADAPTIVE_PROFILE_KEY, JSON.stringify(next));
  } catch {}
  return next;
}

function _adaptiveEnabled() {
  return _loadAdaptiveProfile().enabled !== false;
}

// Static half of the adaptive profile — byte-stable across turns so it can live in
// the SYSTEM prompt without breaking the upstream prompt-cache prefix. The per-query
// preference-memory lines moved to _adaptiveMemoryBlock (injected in the per-turn
// dynamic preamble at the user-message tail, same pattern as growth/context blocks).
function _adaptivePromptBlock() {
  const profile = _loadAdaptiveProfile();
  if (profile.enabled === false) return "";
  const memory = "";
  return `\n\n【自适应用户档案】已开启。你要逐步贴近用户的真实工作方式，但这些只是偏好，不覆盖本轮明确指令；若本轮指令冲突，以用户本轮为准。
回答风格：${_adaptiveOptionLabel("tone", profile.tone)}。
细节密度：${_adaptiveOptionLabel("detail", profile.detail)}。
执行节奏：${_adaptiveOptionLabel("autonomy", profile.autonomy)}。
用户熟练度：${_adaptiveOptionLabel("skill", profile.skill)}。
意图识别：${_adaptiveOptionLabel("intentMode", profile.intentMode)}。
自适应理解规则：
- 用户表达很短、很乱、带情绪，或只说“啊 / ？？ / 继续 / 这个 / 不是这个 / 没懂 / 怎么回事”时，先结合最近对话、当前 UI/截图、刚完成或失败的动作、打开文件和任务状态推断他精确指的是什么；置信高就直接处理，并用一句话说明你依据哪条上下文判断。
- 用户明显不懂技术或概念时，自动降到新手可理解的说法：先说结论和下一步，再补最少必要解释；不要甩术语、不要让用户自己翻文档。
- 用户纠正你（例如“不是这个”“要中文”“不要改界面”“别打包”）时，把它当成强自适应信号；后续同类任务优先遵守。若是跨项目长期偏好，并且当前模式有 remember 工具，可记为 global 偏好。
- 只有上下文仍不足以唯一判断时，才问；问题必须给 2-3 个具体候选，不要泛泛问“你想做什么”。${memory}`;
}

// Per-query preference recall for the adaptive profile — CONTENT VARIES with the
// query, so it must ride the per-turn dynamic preamble (user-message tail), never
// the system prompt: one changed byte in the system prefix voids the whole cache.
function _adaptiveMemoryBlock(query = "") {
  const profile = _loadAdaptiveProfile();
  if (profile.enabled === false) return "";
  let preferenceLines = [];
  try {
    preferenceLines = _kgRetrieve("", query || "用户 偏好 工作习惯 回答风格", 5, 8)
      .filter((n) => n?.type === "preference" || /用户|喜欢|偏好|要求|不要|希望|prefer/i.test(n?.content || ""))
      .map((n) => `- ${n.content}`);
  } catch {}
  if (!preferenceLines.length) return "";
  return `📎 长期偏好记忆（自适应档案，供本轮参考；与本轮明确指令冲突时以指令为准）：\n${preferenceLines.join("\n").slice(0, 1400)}`;
}

function renderAdaptiveTool(body) {
  createToolHeader(body, "自适应", "让 AI 逐步记住你的表达偏好、工作方式和通用规则；越用越贴近你，但本轮明确要求永远优先。");
  let profile = _loadAdaptiveProfile();
  const persistProfile = () => { profile = _saveAdaptiveProfile(profile); };
  const makeRow = (label, hint, control) => {
    const row = document.createElement("div");
    row.className = "settings-row";
    const meta = document.createElement("div");
    meta.className = "settings-row__meta";
    const lbl = document.createElement("span");
    lbl.className = "settings-row__label";
    lbl.textContent = label;
    meta.appendChild(lbl);
    if (hint) {
      const h = document.createElement("span");
      h.className = "settings-row__hint";
      h.textContent = hint;
      meta.appendChild(h);
    }
    const ctrl = document.createElement("div");
    ctrl.className = "settings-row__control";
    ctrl.appendChild(control);
    row.append(meta, ctrl);
    return row;
  };
  const makeSelect = (key) => {
    const sel = document.createElement("select");
    sel.className = "settings-input";
    for (const [value, label] of ADAPTIVE_PROFILE_OPTIONS[key]) {
      const opt = document.createElement("option");
      opt.value = value;
      opt.textContent = label;
      if (profile[key] === value) opt.selected = true;
      sel.appendChild(opt);
    }
    sel.addEventListener("change", () => {
      profile[key] = sel.value;
      persistProfile();
    });
    return sel;
  };

  const sec = document.createElement("div");
  sec.className = "settings-group";
  const title = document.createElement("h3");
  title.className = "settings-group__title";
  title.textContent = "AI 自适应";
  sec.appendChild(title);

  const sw = document.createElement("button");
  sw.type = "button";
  sw.className = "settings-toggle" + (profile.enabled ? " is-on" : "");
  sw.setAttribute("role", "switch");
  sw.setAttribute("aria-checked", String(profile.enabled));
  sw.innerHTML = `<span class="settings-toggle__knob"></span>`;
  sw.addEventListener("click", () => {
    profile.enabled = !profile.enabled;
    persistProfile();
    sw.classList.toggle("is-on", profile.enabled);
    sw.setAttribute("aria-checked", String(profile.enabled));
    showToast(profile.enabled ? "自适应已开启" : "自适应已关闭");
  });
  sec.appendChild(makeRow("启用自适应", "开启后会把用户级偏好带给模型；关闭后不再自动注入这些偏好。", sw));
  sec.appendChild(makeRow("回答风格", "控制默认语气，不覆盖你每轮明确要求。", makeSelect("tone")));
  sec.appendChild(makeRow("细节密度", "决定默认讲多细：短答、平衡或深入。", makeSelect("detail")));
  sec.appendChild(makeRow("执行节奏", "决定 AI 默认是主动推进，还是关键处先确认。", makeSelect("autonomy")));
  sec.appendChild(makeRow("用户熟练度", "用户不懂时自动讲人话；用户像老手时少废话。", makeSelect("skill")));
  sec.appendChild(makeRow("意图识别", "短句、截图指代、情绪反馈优先结合上下文推断。", makeSelect("intentMode")));

  const notes = document.createElement("textarea");
  notes.className = "settings-input adaptive-notes";
  notes.spellcheck = false;
  notes.placeholder = "一行一条，例如：\n前端默认用 shadcn/ui + Tailwind，浅色 Google 风格。\n修 bug 必须先找根因再改。\n如果我只说“啊/？？/不是这个”，先结合上下文判断我卡在哪里。\n回答不要空话，要讲真实依据。";
  notes.value = _kgText("");
  const noteRow = makeRow("长期偏好记忆", "保存到全局用户偏好，所有项目都会按任务相关性召回。", notes);
  noteRow.classList.add("settings-row--stack");
  sec.appendChild(noteRow);
  body.appendChild(sec);

  const actions = document.createElement("div");
  actions.className = "tool-actions settings-actions";
  const save = document.createElement("button");
  save.className = "btn btn--primary";
  save.type = "button";
  save.textContent = "保存自适应档案";
  save.addEventListener("click", () => {
    persistProfile();
    const count = _saveKgText("", notes.value);
    showToast(`自适应档案已保存：全局偏好 ${count} 条`);
  });
  const reset = document.createElement("button");
  reset.className = "btn";
  reset.type = "button";
  reset.textContent = "恢复默认自适应";
  reset.addEventListener("click", () => {
    profile = _saveAdaptiveProfile(DEFAULT_ADAPTIVE_PROFILE);
    renderFeaturePanel();
    showToast("自适应设置已恢复默认");
  });
  const memory = document.createElement("button");
  memory.className = "btn";
  memory.type = "button";
  memory.textContent = "打开记忆中心";
  memory.addEventListener("click", openMemoryPanel);
  actions.append(save, reset, memory);
  body.appendChild(actions);
}

