async function updateEditorPreference(key, value, { rerender = false } = {}) {
  _editorPrefs = _editorPrefs || {};
  if (key === "locale") value = coerceSupportedLocale(value, DEFAULT_EDITOR_SETTINGS.locale);
  if (key === "country") value = normalizeCountryCode(value, DEFAULT_EDITOR_SETTINGS.country);
  if (key === "theme") value = normalizeTheme(value);
  if (key === "appIcon") value = normalizeAppIcon(value);
  _editorPrefs[key] = value;
  await saveEditorPrefs();
  if (key === "theme") {
    await setTheme(value);
    return;
  }
  if (key === "appIcon") {
    applyAppIcon(value);
    if (rerender) renderFeaturePanel();
    return;
  }
  if (key === "locale") {
    await setLocale(value);
    showToast(t("feature.settings.localeSwitched", { language: localeDisplayName(value, value) }));
    renderFeaturePanel();
    return;
  }
  if (key === "country") {
    try { localStorage.setItem("michael-ide-country", value); } catch {}
    showToast(t("feature.settings.countrySwitched", { country: countryOptionLabel(value, getLocale()) }));
    if (document.querySelector(".pf-ov")) { try { showProfile(); } catch {} }
    return;
  }
  applyEditorPrefs();
  if (rerender) renderFeaturePanel();
}

function buildSettingControl(item, cur, update) {
  const control = document.createElement("div");
  control.className = "settings-row__control";

  if (item.type === "select") {
    const sel = document.createElement("select");
    sel.className = "settings-input";
    const options = typeof item.options === "function" ? item.options(cur) : item.options;
    for (const [val, text] of options) {
      const opt = document.createElement("option");
      opt.value = val;
      opt.textContent = text;
      if (String(val) === String(cur)) opt.selected = true;
      sel.appendChild(opt);
    }
    sel.addEventListener("change", () => update(item.key, sel.value));
    control.appendChild(sel);
  } else if (item.type === "number") {
    const inp = document.createElement("input");
    inp.type = "number";
    inp.className = "settings-input settings-input--num";
    inp.value = cur;
    if (item.min != null) inp.min = item.min;
    if (item.max != null) inp.max = item.max;
    inp.addEventListener("change", () => update(item.key, Number(inp.value)));
    control.appendChild(inp);
  } else if (item.type === "text") {
    const inp = document.createElement("input");
    inp.type = "text";
    inp.className = "settings-input settings-input--text";
    inp.value = cur;
    inp.addEventListener("change", () => update(item.key, inp.value));
    control.appendChild(inp);
  } else if (item.type === "toggle") {
    const sw = document.createElement("button");
    sw.type = "button";
    sw.className = "settings-toggle" + (cur !== false ? " is-on" : "");
    sw.setAttribute("role", "switch");
    sw.setAttribute("aria-checked", String(cur !== false));
    sw.innerHTML = `<span class="settings-toggle__knob"></span>`;
    sw.addEventListener("click", () => {
      const on = !sw.classList.contains("is-on");
      sw.classList.toggle("is-on", on);
      sw.setAttribute("aria-checked", String(on));
      update(item.key, on);
    });
    control.appendChild(sw);
  }
  return control;
}

function buildSettingsRow(item, cur, update) {
  const row = document.createElement("div");
  row.className = "settings-row";

  const meta = document.createElement("div");
  meta.className = "settings-row__meta";
  const lbl = document.createElement("span");
  lbl.className = "settings-row__label";
  lbl.textContent = item.labelKey ? t(item.labelKey) : item.label;
  meta.appendChild(lbl);
  const hintText = item.hintKey ? t(item.hintKey) : item.hint;
  if (hintText) {
    const hint = document.createElement("span");
    hint.className = "settings-row__hint";
    hint.textContent = hintText;
    meta.appendChild(hint);
  }
  row.append(meta, buildSettingControl(item, cur, update));
  return row;
}

