function readFileAsDataUrl(file) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => resolve(String(reader.result || ""));
    reader.onerror = () => reject(new Error(t("feature.appearance.appIcon.readFailed")));
    reader.readAsDataURL(file);
  });
}

function loadImageDataUrl(src) {
  return new Promise((resolve, reject) => {
    const img = new Image();
    img.onload = () => resolve(img);
    img.onerror = () => reject(new Error(t("feature.appearance.appIcon.invalid")));
    img.src = src;
  });
}

async function appIconFromFile(file) {
  if (!file || !String(file.type || "").startsWith("image/")) {
    throw new Error(t("feature.appearance.appIcon.invalid"));
  }
  if (file.size > 8 * 1024 * 1024) {
    throw new Error(t("feature.appearance.appIcon.tooLarge"));
  }
  const raw = await readFileAsDataUrl(file);
  if (/^data:image\/svg\+xml;base64,/i.test(raw)) {
    if (!normalizeAppIcon(raw)) throw new Error(t("feature.appearance.appIcon.tooLarge"));
    return raw;
  }
  const img = await loadImageDataUrl(raw);
  const w = img.naturalWidth || img.width;
  const h = img.naturalHeight || img.height;
  if (!w || !h) throw new Error(t("feature.appearance.appIcon.invalid"));
  const canvas = document.createElement("canvas");
  const size = 256;
  canvas.width = size;
  canvas.height = size;
  const ctx = canvas.getContext("2d");
  if (!ctx) throw new Error(t("feature.appearance.appIcon.invalid"));
  ctx.clearRect(0, 0, size, size);
  const side = Math.min(w, h);
  const sx = Math.max(0, (w - side) / 2);
  const sy = Math.max(0, (h - side) / 2);
  ctx.drawImage(img, sx, sy, side, side, 0, 0, size, size);
  let out = canvas.toDataURL("image/png");
  if (!normalizeAppIcon(out)) out = canvas.toDataURL("image/webp", 0.92);
  if (!normalizeAppIcon(out)) throw new Error(t("feature.appearance.appIcon.tooLarge"));
  return out;
}

function renderAppIconSettings(body, p) {
  const sec = document.createElement("div");
  sec.className = "settings-group appearance-app-icon-group";
  const h = document.createElement("h3");
  h.className = "settings-group__title";
  h.textContent = t("feature.appearance.appIcon.section");
  sec.appendChild(h);

  const row = document.createElement("div");
  row.className = "settings-row settings-row--app-icon";
  const meta = document.createElement("div");
  meta.className = "settings-row__meta";
  const label = document.createElement("span");
  label.className = "settings-row__label";
  label.textContent = t("feature.appearance.appIcon.label");
  const hint = document.createElement("span");
  hint.className = "settings-row__hint";
  hint.textContent = t("feature.appearance.appIcon.hint");
  meta.append(label, hint);

  const input = document.createElement("input");
  input.type = "file";
  input.accept = "image/*";
  input.hidden = true;

  const control = document.createElement("div");
  control.className = "settings-row__control app-icon-control";
  const preview = document.createElement("div");
  preview.className = "app-icon-preview";
  const img = document.createElement("img");
  img.className = "assistant-logo";
  img.dataset.appIcon = "true";
  img.alt = "";
  img.src = appIconSrc(p.appIcon);
  preview.appendChild(img);

  const actions = document.createElement("div");
  actions.className = "app-icon-actions";
  const upload = document.createElement("button");
  upload.type = "button";
  upload.className = "btn btn--primary";
  upload.textContent = t("feature.appearance.appIcon.upload");
  const reset = document.createElement("button");
  reset.type = "button";
  reset.className = "btn";
  reset.textContent = t("feature.appearance.appIcon.reset");
  reset.disabled = !normalizeAppIcon(p.appIcon);
  actions.append(upload, reset);
  control.append(preview, actions, input);
  row.append(meta, control);
  sec.appendChild(row);
  body.appendChild(sec);

  upload.addEventListener("click", () => input.click());
  input.addEventListener("change", async () => {
    const file = input.files && input.files[0];
    input.value = "";
    if (!file) return;
    upload.disabled = true;
    upload.textContent = t("feature.appearance.appIcon.processing");
    try {
      const icon = await appIconFromFile(file);
      await updateEditorPreference("appIcon", icon, { rerender: true });
      showToast(t("feature.appearance.appIcon.applied"));
    } catch (e) {
      showToast(e?.message || t("feature.appearance.appIcon.invalid"));
    } finally {
      upload.disabled = false;
      upload.textContent = t("feature.appearance.appIcon.upload");
    }
  });
  reset.addEventListener("click", async () => {
    await updateEditorPreference("appIcon", "", { rerender: true });
    showToast(t("feature.appearance.appIcon.resetDone"));
  });
}

