async function renderSettingsTool(body) {
  await loadEditorPrefs();
  const p = effectivePrefs();
  const desiredLocale = coerceSupportedLocale(p.locale || DEFAULT_EDITOR_SETTINGS.locale, DEFAULT_EDITOR_SETTINGS.locale);
  if (getLocale() !== desiredLocale) await setLocale(desiredLocale);
  createToolHeader(body, t("feature.settings.title"), t("feature.settings.desc"));

  const update = async (key, value) => {
    await updateEditorPreference(key, value);
  };

  for (const section of SETTINGS_SCHEMA) {
    const sec = document.createElement("div");
    sec.className = "settings-group";
    const h = document.createElement("h3");
    h.className = "settings-group__title";
    h.textContent = section.groupKey ? t(section.groupKey) : section.group;
    sec.appendChild(h);

    for (const item of section.items) sec.appendChild(buildSettingsRow(item, p[item.key], update));
    body.appendChild(sec);
  }

  const createSwitch = (isOn, onToggle) => {
    const sw = document.createElement("button");
    sw.type = "button";
    sw.className = "settings-toggle" + (isOn ? " is-on" : "");
    sw.setAttribute("role", "switch");
    sw.setAttribute("aria-checked", String(isOn));
    sw.innerHTML = `<span class="settings-toggle__knob"></span>`;
    sw.addEventListener("click", () => {
      const next = !sw.classList.contains("is-on");
      sw.classList.toggle("is-on", next);
      sw.setAttribute("aria-checked", String(next));
      onToggle(next);
    });
    return sw;
  };
  const createSettingsRow = (label, hint, control) => {
    const row = document.createElement("div");
    row.className = "settings-row";
    const meta = document.createElement("div");
    meta.className = "settings-row__meta";
    const lbl = document.createElement("span");
    lbl.className = "settings-row__label";
    lbl.textContent = label;
    meta.appendChild(lbl);
    if (hint) {
      const h = document.createElement("span");
      h.className = "settings-row__hint";
      h.textContent = hint;
      meta.appendChild(h);
    }
    const box = document.createElement("div");
    box.className = "settings-row__control";
    box.appendChild(control);
    row.append(meta, box);
    return row;
  };
  const aiSec = document.createElement("div");
  aiSec.className = "settings-group";
  const aiTitle = document.createElement("h3");
  aiTitle.className = "settings-group__title";
  aiTitle.textContent = t("feature.settings.ai.title");
  aiSec.appendChild(aiTitle);
  // 这里曾有一个「逐操作审批」开关。它是个空承诺：`run.perm` 全代码库零处被读取，
  // `_approveToolCall` 恒返回 true 且没有任何调用点 —— 打开它不会让任何工具调用需要
  // 确认。与其让用户以为自己有一层保护，不如让「没有审批」成为诚实可见的事实。
  //
  // 真正在生效的门是针对**外部内容**的：仓库自带的可执行配置（hooks）要一次性确认，
  // 仓库自带的 MCP 配置根本不读。见 _approveWorkspaceExecConfig。
  aiSec.appendChild(createSettingsRow(
    t("feature.settings.liveFollow.label"),
    t("feature.settings.liveFollow.hint"),
    createSwitch(_liveStageOn(), (on) => {
      _setLiveStage(on);
      showToast(on ? t("feature.settings.liveFollowOn") : t("feature.settings.liveFollowOff"));
    }),
  ));
  body.appendChild(aiSec);

  const actions = document.createElement("div");
  actions.className = "tool-actions settings-actions";
  const reset = document.createElement("button");
  reset.className = "btn";
  reset.type = "button";
  reset.textContent = t("feature.settings.reset");
  reset.addEventListener("click", async () => {
    _editorPrefs = {};
    await saveEditorPrefs();
    applyEditorPrefs();
    renderFeaturePanel();
  });
  actions.appendChild(reset);
  body.appendChild(actions);
}

