// Hoisted so buildMenubar can remove the PRIOR build's document-level listeners before re-adding —
// buildMenubar re-runs on every Auto-Save toggle, and these two would otherwise stack on `document`.
let _menubarDocClick = null, _menubarDocKey = null;
function buildMenubar() {
  const bar = $("menubar");
  if (!bar) return;
  bar.innerHTML = "";
  const buttons = [];
  const panels = [];
  let openIdx = -1;

  const closeMenu = () => {
    if (openIdx < 0) return;
    panels[openIdx].hidden = true;
    buttons[openIdx].classList.remove("is-open");
    buttons[openIdx].setAttribute("aria-expanded", "false");
    openIdx = -1;
  };
  const openMenu = (i) => {
    if (openIdx === i) return;
    closeMenu();
    panels[i].hidden = false;
    buttons[i].classList.add("is-open");
    buttons[i].setAttribute("aria-expanded", "true");
    openIdx = i;
  };

  const MENUS = getMenus();
  MENUS.forEach((menu, i) => {
    const wrap = document.createElement("div");
    wrap.className = "tb-menu";
    const btn = document.createElement("button");
    btn.type = "button";
    btn.className = "tb-menu__btn";
    btn.textContent = menu.label;
    btn.setAttribute("aria-haspopup", "true");
    btn.setAttribute("aria-expanded", "false");
    const panel = document.createElement("div");
    panel.className = "menu menu--tb";
    panel.setAttribute("role", "menu");
    panel.hidden = true;
    for (const entry of menu.items) {
      if (entry.sep) {
        const sep = document.createElement("div");
        sep.className = "menu__sep";
        panel.appendChild(sep);
        continue;
      }
      const mi = document.createElement("div");
      mi.className = "menu__item";
      mi.setAttribute("role", "menuitem");
      mi.innerHTML =
        (entry.icon ? `<svg class="ic" aria-hidden="true"><use href="#${entry.icon}" /></svg>` : "") +
        `<span class="name"></span>` +
        (entry.hint ? `<span class="meta"></span>` : "");
      mi.querySelector(".name").textContent = entry.label;
      if (entry.hint) mi.querySelector(".meta").textContent = entry.hint;
      mi.addEventListener("click", () => {
        closeMenu();
        try {
          entry.action();
        } catch (e) {
          showToast(String(e));
        }
      });
      panel.appendChild(mi);
    }
    btn.addEventListener("click", (e) => {
      e.stopPropagation();
      if (openIdx === i) closeMenu();
      else openMenu(i);
    });
    btn.addEventListener("mouseenter", () => {
      if (openIdx >= 0) openMenu(i);
    });
    wrap.append(btn, panel);
    bar.appendChild(wrap);
    buttons.push(btn);
    panels.push(panel);
  });

  // Remove the previous build's handlers before re-adding, so repeated buildMenubar() calls
  // (every Auto-Save toggle) never leak stacked document listeners capturing stale menubar state.
  if (_menubarDocClick) document.removeEventListener("click", _menubarDocClick);
  if (_menubarDocKey) document.removeEventListener("keydown", _menubarDocKey);
  _menubarDocClick = (e) => { if (openIdx >= 0 && !bar.contains(e.target)) closeMenu(); };
  _menubarDocKey = (e) => { if (e.key === "Escape") closeMenu(); };
  document.addEventListener("click", _menubarDocClick);
  document.addEventListener("keydown", _menubarDocKey);
}

// ---- wiring ----
async function chooseFolder() {
  let picked = null, errored = false;
  const t0 = Date.now();
  try { picked = await backend.pickFolder(); }
  catch { errored = true; } // native dialog threw (unavailable on this desktop)
  if (picked) { await openFolder(picked); return; }
  // No folder chosen. Show the manual path entry ONLY when the native picker
  // didn't really work — it threw, or resolved suspiciously fast (<400ms) meaning
  // no dialog actually opened (e.g. Linux without xdg-desktop-portal, which made
  // the button look dead). A real user CANCEL takes longer than that, so cancelling
  // the macOS picker no longer pops a second modal.
  if (errored || Date.now() - t0 < 400) await _promptFolderPath();
}

// Manual "open folder" via typed/pasted path + recent list — the reliable
// fallback when the OS file picker is unavailable. `onPick` lets the same modal
// either OPEN a project (default, replaces the workspace) or ADD a folder to the
// current multi-root workspace; `title` labels it accordingly.
async function _promptFolderPath(opts) {
  const onPick = (opts && opts.onPick) || openFolder;
  const title = (opts && opts.title) || "打开文件夹";
  let home = "";
  try { home = (await backend.homeDir()) || ""; } catch {}
  home = home || rootPath || "";
  let recents = [];
  try { const store = await loadStore("session.json"); recents = (await store.get(RECENT_PROJECTS_KEY)) || []; } catch {}

  const overlay = document.createElement("div");
  overlay.style.cssText = "position:fixed;inset:0;background:rgba(0,0,0,.45);display:flex;align-items:center;justify-content:center;z-index:99999";
  const modal = document.createElement("div");
  modal.style.cssText = "width:min(560px,92vw);background:var(--panel,#1e1e22);border:1px solid var(--border,rgba(128,128,128,.35));border-radius:12px;box-shadow:0 20px 60px rgba(0,0,0,.5);overflow:hidden";
  modal.innerHTML =
    `<div style="display:flex;align-items:center;gap:8px;padding:12px 14px;border-bottom:1px solid var(--border,rgba(128,128,128,.25))">` +
      `<svg viewBox="0 0 16 16" width="15" height="15" fill="currentColor"><path d="M1.75 1A1.75 1.75 0 000 2.75v10.5C0 14.216.784 15 1.75 15h12.5A1.75 1.75 0 0016 13.25v-8.5A1.75 1.75 0 0014.25 3H7.5a.25.25 0 01-.2-.1l-.9-1.2C6.07 1.26 5.55 1 5 1H1.75z"/></svg>` +
      `<span style="font-size:14px;font-weight:600">${title}</span>` +
      `<button class="pf-close" type="button" style="margin-left:auto;background:none;border:none;color:inherit;cursor:pointer;font-size:16px;opacity:.6">✕</button>` +
    `</div>` +
    `<div style="padding:12px 14px">` +
      `<div style="font-size:12px;opacity:.65;margin-bottom:6px">输入或粘贴文件夹的完整路径：</div>` +
      `<input class="pf-input" type="text" spellcheck="false" placeholder="${_escAttr(home || "/path/to/project")}" style="width:100%;box-sizing:border-box;padding:9px 10px;font:13px/1.4 ui-monospace,Menlo,monospace;background:var(--bg,#15151a);color:var(--text,#eee);border:1px solid var(--border,rgba(128,128,128,.3));border-radius:8px;outline:none">` +
      `<div class="pf-err" style="color:#f85149;font-size:12px;min-height:16px;margin-top:6px"></div>` +
      (recents.length ? `<div style="font-size:12px;opacity:.6;margin:2px 0 4px">最近打开：</div><div class="pf-recents" style="display:flex;flex-direction:column;gap:1px;max-height:150px;overflow:auto"></div>` : "") +
    `</div>` +
    `<div style="display:flex;gap:8px;padding:0 14px 14px;justify-content:flex-end">` +
      `<button class="pf-cancel" type="button" style="padding:6px 12px;border-radius:7px;border:1px solid var(--border,rgba(128,128,128,.35));background:none;color:inherit;cursor:pointer;font:inherit;font-size:12px">取消</button>` +
      `<button class="pf-open" type="button" style="padding:6px 14px;border-radius:7px;border:none;background:var(--accent,#3b82f6);color:#fff;cursor:pointer;font:inherit;font-size:12px">打开</button>` +
    `</div>`;
  overlay.appendChild(modal);
  document.body.appendChild(overlay);

  const input = modal.querySelector(".pf-input");
  const errEl = modal.querySelector(".pf-err");
  input.value = home;
  setTimeout(() => { input.focus(); input.select(); }, 30);
  const close = () => overlay.remove();
  const tryOpen = async (path) => {
    const p = (path || "").trim().replace(/^['"]|['"]$/g, "");
    if (!p) { errEl.textContent = "请输入路径"; return; }
    try { await backend.readDir(p); }
    catch { errEl.textContent = "找不到这个文件夹（检查路径是否写对）"; return; }
    close();
    await onPick(p);
  };
  modal.querySelector(".pf-close").addEventListener("click", close);
  modal.querySelector(".pf-cancel").addEventListener("click", close);
  overlay.addEventListener("click", (e) => { if (e.target === overlay) close(); });
  modal.querySelector(".pf-open").addEventListener("click", () => tryOpen(input.value));
  input.addEventListener("keydown", (e) => { if (e.key === "Enter") { e.preventDefault(); tryOpen(input.value); } else if (e.key === "Escape") close(); });

  const recentsBox = modal.querySelector(".pf-recents");
  if (recentsBox) {
    for (const rp of recents.slice(0, 8)) {
      const path = typeof rp === "string" ? rp : (rp && rp.path);
      if (!path) continue;
      const b = document.createElement("button");
      b.type = "button";
      b.style.cssText = "text-align:left;padding:6px 8px;border-radius:6px;border:none;background:none;color:inherit;cursor:pointer;font:12px ui-monospace,Menlo,monospace;opacity:.85;white-space:nowrap;overflow:hidden;text-overflow:ellipsis";
      b.textContent = path;
      b.addEventListener("mouseenter", () => { b.style.background = "rgba(128,128,128,.15)"; });
      b.addEventListener("mouseleave", () => { b.style.background = "none"; });
      b.addEventListener("click", () => tryOpen(path));
      recentsBox.appendChild(b);
    }
  }
}
$("openFolderBtn").addEventListener("click", chooseFolder);
$("emptyOpenBtn").addEventListener("click", chooseFolder);
// Welcome-screen "打开文件夹" button — was a DUPLICATE id="emptyOpenBtn", so
// getElementById only wired the first one and this big button did nothing.
$("welcomeOpenBtn")?.addEventListener("click", () => {
  const root = rootPath || workspaceRoots[0] || "";
  if (root) newEntry(root, false);
  else chooseFolder();
});
// settings dropdown
// 齿轮与菜单项全部改在 pointerdown 上响应（同侧边栏页签的修复）：AI 回复期间渲染繁忙，
// WKWebView 的 click（按下+松开配对）常被吞——账单/通用设置/快捷键点了没反应。
// pointerdown 一按即达；同一次按压派生的后续 click 用一次性捕获吞掉，防它落到菜单
// 关闭后暴露的底层元素或 document 关单逻辑上。键盘 Enter/Space（合成 click，detail===0）保留。
const settingsDropdown = $("settingsDropdown");
const _swallowNextClick = () => {
  const eat = (e) => { e.stopPropagation(); e.preventDefault(); };
  document.addEventListener("click", eat, { capture: true, once: true });
  setTimeout(() => document.removeEventListener("click", eat, { capture: true }), 350);
};
$("settingsBtn").addEventListener("pointerdown", (e) => {
  if (e.button !== 0) return;
  e.stopPropagation();
  _swallowNextClick();
  if (settingsDropdown) settingsDropdown.hidden = !settingsDropdown.hidden;
});
$("settingsBtn").addEventListener("click", (e) => {
  e.stopPropagation();
  if (e.detail === 0 && settingsDropdown) settingsDropdown.hidden = !settingsDropdown.hidden; // 键盘可达
});
// 按在菜单外 → 关单（pointerdown 保证回复期间也能可靠关闭）；click 路径保留为兜底。
document.addEventListener("pointerdown", (e) => {
  if (!settingsDropdown || settingsDropdown.hidden) return;
  if (settingsDropdown.contains(e.target) || $("settingsBtn").contains(e.target)) return;
  settingsDropdown.hidden = true;
});
document.addEventListener("click", () => { if (settingsDropdown) settingsDropdown.hidden = true; });
if (settingsDropdown) {
  const _dropdownActivate = (item) => {
    settingsDropdown.hidden = true;
    const action = item.dataset.action;
    if (action === "general-settings") openFeaturePanel("settings");
    else if (action === "shortcuts") openFeaturePanel("shortcuts");
    else if (action === "billing") { _showBillingPanel(); }
    else if (action === "login") {
      const dlg = $("loginDialog");
      if (dlg) { _resetLoginUI(); const em = $("loginEmail"); if (em) em.value = ""; dlg.showModal(); setTimeout(() => em?.focus(), 0); }
    }
    else if (action === "logout") {
      _doLogout();
    }
    else if (action === "profile") {
      showProfile();
    }
  };
  settingsDropdown.addEventListener("pointerdown", (e) => {
    if (e.button !== 0) return;
    e.stopPropagation();
    const item = e.target.closest("[data-action]");
    if (!item) return;
    _swallowNextClick();
    _dropdownActivate(item);
  });
  settingsDropdown.addEventListener("click", (e) => {
    e.stopPropagation();
    if (e.detail !== 0) return; // 鼠标路径已由 pointerdown 处理
    const item = e.target.closest("[data-action]");
    if (item) _dropdownActivate(item);
  });
}
