async function showNewProjectDialog() {
  document.querySelector(".new-project-overlay")?.remove();

  // 创建位置：记住上次选的父目录；首次默认 ~/Desktop（用户现有项目都在桌面）。
  let _newProjectParentDir = localStorage.getItem("michael-ide.new-project-dir") || "";
  if (!_newProjectParentDir) {
    try { _newProjectParentDir = ((await backend.homeDir()) || "").replace(/\/+$/, "") + "/Desktop"; } catch { _newProjectParentDir = "~"; }
  }

  const overlay = document.createElement("div");
  overlay.className = "new-project-overlay";
  const modal = document.createElement("div");
  modal.className = "new-project-dialog";
  modal.setAttribute("role", "dialog");
  modal.setAttribute("aria-modal", "true");
  modal.setAttribute("aria-labelledby", "newProjectTitle");
  modal.innerHTML = `
    <div class="new-project-head">
      <div class="new-project-brand" aria-hidden="true">
        <svg viewBox="0 0 48 48"><path d="M7 15.5A5.5 5.5 0 0 1 12.5 10H20l3.4 4H35.5A5.5 5.5 0 0 1 41 19.5v13A5.5 5.5 0 0 1 35.5 38h-23A5.5 5.5 0 0 1 7 32.5v-17Z" fill="#E8F0FE"/><path d="M7 20h34v12.5A5.5 5.5 0 0 1 35.5 38h-23A5.5 5.5 0 0 1 7 32.5V20Z" fill="#1A73E8"/><path d="M12.5 10H20l3.4 4H41v6H7v-4.5A5.5 5.5 0 0 1 12.5 10Z" fill="#FBBC04"/></svg>
      </div>
      <div class="new-project-titleblock">
        <h2 id="newProjectTitle">新建项目</h2>
        <p>选择一个真实模板，Michael IDE 会在终端里创建并安装依赖。</p>
      </div>
      <button class="new-project-close" type="button" aria-label="关闭">
        <svg viewBox="0 0 24 24" aria-hidden="true"><path d="M6 6l12 12M18 6 6 18" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"/></svg>
      </button>
    </div>
    <div class="new-project-body">
      <label class="new-project-name-field">
        <span>项目名称</span>
        <div class="new-project-input-wrap">
          <svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 7.5A2.5 2.5 0 0 1 6.5 5h3.2l2 2.4h5.8A2.5 2.5 0 0 1 20 9.9v6.6a2.5 2.5 0 0 1-2.5 2.5h-11A2.5 2.5 0 0 1 4 16.5v-9Z" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linejoin="round"/></svg>
          <input class="new-project-name-input" placeholder="my-project" autocomplete="off" spellcheck="false" autofocus>
        </div>
      </label>
      <div class="new-project-template-label">项目模板</div>
      <div class="new-project-template-list" role="listbox" aria-label="项目模板"></div>
    </div>
    <div class="new-project-footer">
      <div class="new-project-hint"><button class="new-project-location" type="button" title="更改创建位置">📁 <span class="new-project-location-path"></span> · 更改…</button></div>
      <div class="new-project-actions">
        <button class="new-project-cancel" type="button">取消</button>
        <button class="new-project-create" type="button">创建项目</button>
      </div>
    </div>`;

  const nameInput = modal.querySelector(".new-project-name-input");
  const list = modal.querySelector(".new-project-template-list");
  const createBtn = modal.querySelector(".new-project-create");
  // 位置行：显示当前创建目录，点击可换（记忆到 localStorage）。
  const locBtn = modal.querySelector(".new-project-location");
  const locPath = modal.querySelector(".new-project-location-path");
  const _syncLoc = () => { if (locPath) locPath.textContent = _newProjectParentDir; };
  _syncLoc();
  locBtn?.addEventListener("click", async () => {
    try {
      const picked = await backend.pickFolder();
      if (picked && typeof picked === "string") {
        _newProjectParentDir = picked;
        try { localStorage.setItem("michael-ide.new-project-dir", picked); } catch {}
        _syncLoc();
      }
    } catch {}
  });
  let selectedIndex = 0;
  let creating = false;
  const close = () => { overlay.remove(); };
  // 本弹窗全部改 pointerdown 响应（同侧边栏/设置菜单的修复）：WKWebView 丢 click 时，
  // 模板卡点了不选中→永远创建默认的 React 模板（"每个框架内容都一样"）。
  const _npSwallowNextClick = () => {
    const eat = (e) => { e.stopPropagation(); e.preventDefault(); };
    document.addEventListener("click", eat, { capture: true, once: true });
    setTimeout(() => document.removeEventListener("click", eat, { capture: true }), 350);
  };
  modal.querySelector(".new-project-close").addEventListener("pointerdown", (e) => { if (e.button === 0) { _npSwallowNextClick(); close(); } });
  modal.querySelector(".new-project-cancel").addEventListener("pointerdown", (e) => { if (e.button === 0) { _npSwallowNextClick(); close(); } });
  modal.querySelector(".new-project-close").addEventListener("click", close);
  modal.querySelector(".new-project-cancel").addEventListener("click", close);
  overlay.addEventListener("click", (e) => { if (e.target === overlay) close(); });

  const syncSelection = () => {
    list.querySelectorAll(".new-project-template").forEach((row, idx) => {
      const selected = idx === selectedIndex;
      row.classList.toggle("is-selected", selected);
      row.setAttribute("aria-selected", selected ? "true" : "false");
      row.tabIndex = selected ? 0 : -1;
    });
  };

  const createProject = async (tmpl = PROJECT_TEMPLATES[selectedIndex] || PROJECT_TEMPLATES[0]) => {
    if (creating || !tmpl) return;
    creating = true;
    createBtn.disabled = true;
    createBtn.textContent = "创建中…";
    const name = nameInput.value.trim() || "my-project";
    const parentDirPath = _newProjectParentDir;
    const projectPath = parentDirPath.replace(/\/+$/, "") + "/" + name;
    // 创建前校验失败 → 不关弹窗，按钮复位，给出原因，绝不把命令丢进终端碎掉。
    const _resetCreateBtn = () => { creating = false; createBtn.disabled = false; createBtn.textContent = "创建项目"; };
    // ① 重名目录：目标已存在就拒绝——旧版不查，脚手架失败后轮询把**残留的旧同名目录**
    // 当成新项目打开（Flutter 没装失败却"打开了一个 React 项目"就是这么来的）。
    try {
      if (await _pathExistsAsDir(projectPath)) {
        showToast(`⚠️ 目录已存在：${projectPath}，请换个项目名或先删掉旧目录`, { duration: 6000 });
        _resetCreateBtn();
        try { nameInput.focus(); nameInput.select(); } catch {}
        return;
      }
    } catch {}
    // ② 工具链检查：模板依赖的 CLI 没装就明确告知怎么装，不让用户在终端里看
    // "command not found"自己猜（真实终端登录 shell 里探测，PATH 与实际执行一致）。
    const _toolHints = {
      flutter: "安装 Flutter SDK：brew install --cask flutter，或去 flutter.dev 下载",
      go: "安装 Go：brew install go",
      cargo: "安装 Rust：curl https://sh.rustup.rs -sSf | sh",
      python3: "安装 Python：brew install python",
      npm: "安装 Node.js：brew install node，或去 nodejs.org 下载",
      curl: "安装 curl：brew install curl",
    };
    const _needTools = [];
    if (/\bflutter\b/.test(tmpl.cmd)) _needTools.push("flutter");
    if (/\bcargo\b/.test(tmpl.cmd)) _needTools.push("cargo");
    if (/\bgo mod\b/.test(tmpl.cmd)) _needTools.push("go");
    if (/\bpython3\b/.test(tmpl.cmd)) _needTools.push("python3");
    if (/\b(?:npm|npx)\b/.test(tmpl.cmd)) _needTools.push("npm");
    if (/\bcurl\b/.test(tmpl.cmd)) _needTools.push("curl");
    if (inTauri && backend.taskRunCapture) {
      for (const tool of _needTools) {
        try {
          const r = await backend.taskRunCapture(parentDirPath, `command -v ${tool}`, { timeoutSecs: 10 });
          if (!r || r.code !== 0) {
            showToast(`⚠️ 未检测到 ${tool} 命令，无法创建 ${tmpl.name} 项目。${_toolHints[tool] || "请先安装对应工具链"}`, { duration: 8000 });
            _resetCreateBtn();
            return;
          }
        } catch { /* 探测通道异常不阻断：交给终端真实执行去暴露 */ }
      }
    }
    close();
    await openTerminal();
    const wasOpen = termIsOpen();
    if (!wasOpen) {
      await _waitTermReady(3000);
      await new Promise((r) => setTimeout(r, 1800));
    }
    const cmd = tmpl.cmd.replace(/\{\{name\}\}/g, shellQuote(name));
    writeToActiveTerminal(`\n${_clearCmd}\ncd ${shellQuote(parentDirPath)} && ${cmd}\n`);
    showToast(`正在创建 ${tmpl.name} 项目：${projectPath}`);
    // 轮询项目目录出现（脚手架一建目录就打开，不等依赖装完），最多等 5 分钟。
    const t0 = Date.now();
    const poll = async () => {
      if (Date.now() - t0 > 5 * 60 * 1000) return;
      try {
        if (await _pathExistsAsDir(projectPath)) {
          // 无论当前是否开着项目，创建完一律直接打开新项目（用户预期：新建完就进去干活，
          // 旧版"已开项目时只弹提示"导致第二次新建不跳转）。依赖安装继续在终端跑。
          await openFolder(projectPath);
          loadRecentProjects();
          showToast(`✅ 项目已创建并打开：${name}（依赖安装继续在终端进行）`);
          return;
        }
      } catch {}
      setTimeout(poll, 2000);
    };
    setTimeout(poll, 2000);
  };

  for (const tmpl of PROJECT_TEMPLATES) {
    const index = PROJECT_TEMPLATES.indexOf(tmpl);
    const row = document.createElement("button");
    row.type = "button";
    row.className = "new-project-template";
    row.setAttribute("role", "option");
    row.innerHTML = `
      <span class="new-project-template-icon">${projectTemplateIcon(tmpl.icon)}</span>
      <span class="new-project-template-copy">
        <strong>${_escHtml(tmpl.name)}</strong>
        <small>${_escHtml(tmpl.desc)}</small>
      </span>
      <span class="new-project-template-tag">${_escHtml(tmpl.tag)}</span>`;
    row.addEventListener("pointerdown", (e) => { // 一按即选，不依赖易丢的 click
      if (e.button !== 0) return;
      selectedIndex = index;
      syncSelection();
    });
    row.addEventListener("click", () => {
      selectedIndex = index;
      syncSelection();
    });
    row.addEventListener("dblclick", () => createProject(tmpl));
    list.appendChild(row);
  }

  syncSelection();
  createBtn.addEventListener("pointerdown", (e) => { // 创建键同样 pointerdown 即达；creating 标记防重复
    if (e.button !== 0) return;
    _npSwallowNextClick();
    createProject();
  });
  createBtn.addEventListener("click", () => createProject());
  modal.addEventListener("keydown", (e) => {
    if (e.key === "Escape") close();
    if (e.key === "Enter" && (e.metaKey || e.ctrlKey || e.target === nameInput)) {
      e.preventDefault();
      createProject();
    }
    if ((e.key === "ArrowDown" || e.key === "ArrowRight") && document.activeElement?.classList?.contains("new-project-template")) {
      e.preventDefault();
      selectedIndex = Math.min(PROJECT_TEMPLATES.length - 1, selectedIndex + 1);
      syncSelection();
      list.querySelectorAll(".new-project-template")[selectedIndex]?.focus();
    }
    if ((e.key === "ArrowUp" || e.key === "ArrowLeft") && document.activeElement?.classList?.contains("new-project-template")) {
      e.preventDefault();
      selectedIndex = Math.max(0, selectedIndex - 1);
      syncSelection();
      list.querySelectorAll(".new-project-template")[selectedIndex]?.focus();
    }
  });
  overlay.appendChild(modal);
  document.body.appendChild(overlay);
  nameInput.focus();
}

// ---- auto-save ----
let autoSaveEnabled = true;
const autoSaveTimers = new Map();

function scheduleAutoSave(path = activePath) {
  if (!autoSaveEnabled || !path) return;
  const previous = autoSaveTimers.get(path);
  if (previous) clearTimeout(previous);
  const timer = setTimeout(async () => {
    autoSaveTimers.delete(path);
    const f = openFiles.get(path);
    if (f && f.dirty) {
      const snapshot = f.model.getValue();
      try {
        _autoSaving++;
        await _writeOpenFileSnapshot(path, snapshot);
        if (openFiles.get(path) === f && f.model.getValue() === snapshot) {
          markDirty(path, false);
          lspManager?.didSave(path, f.model);
        } else if (openFiles.get(path) === f) {
          // The user kept typing while the save was in flight. The snapshot reached
          // disk, but the newer model must stay dirty and get its own queued save.
          markDirty(path, true);
          scheduleAutoSave(path);
        }
      } catch (e) {
        // Don't fail silently: the buffer stays dirty (so it's not "saved" in the UI)
        // and we warn — otherwise the user keeps typing thinking it's saved and loses
        // it on close. Throttled so a persistent failure doesn't spam every 800ms.
        if (openFiles.get(path) === f) { f.externalConflict = true; markDirty(path, true); }
        const now = Date.now ? Date.now() : 0;
        if (now - _lastAutosaveWarn > 8000) { _lastAutosaveWarn = now; showToast("⚠️ 自动保存失败：" + String(e?.message || e).slice(0, 80) + "（改动仍在，未写入磁盘）"); }
      } finally {
        _autoSaving = Math.max(0, _autoSaving - 1);
      }
    }
  }, 800);
  autoSaveTimers.set(path, timer);
}
let _autoSaving = 0;
let _lastAutosaveWarn = 0;

monacoEditor.onDidChangeModelContent(() => {
  const model = monacoEditor.getModel();
  if (!_imeComposing && !_programmaticModelUpdates.has(model)) scheduleAutoSave(activePath);
});

async function toggleAutoSave() {
  autoSaveEnabled = !autoSaveEnabled;
  if (_editorPrefs) {
    _editorPrefs.autoSave = autoSaveEnabled;
    await saveEditorPrefs();
  }
  showToast(autoSaveEnabled ? t("autosave.enabled") : t("autosave.disabled"));
}

